package com.transportlogistics.app.freight.manifest.adapters.outbound.persistence;
import com.transportlogistics.app.freight.manifest.domain.model.*; import org.springframework.stereotype.Component; import java.util.*;
@Component
class CargoManifestPersistenceMapper {
 CargoManifestEntity toEntity(CargoManifest value){var entity=new CargoManifestEntity();entity.setId(value.id());entity.setManifestNumber(value.manifestNumber());entity.setFreightOrderId(value.freightOrderId());entity.setFreightOrderNumber(value.freightOrderNumber());entity.setVersion(value.version());entity.setCreatedAt(value.createdAt());entity.setUpdatedAt(value.updatedAt());entity.setCreatedBy(value.createdBy());entity.setUpdatedBy(value.updatedBy());entity.setFinalizedAt(value.finalizedAt());entity.setFinalizedBy(value.finalizedBy());var items=new ArrayList<CargoManifestItemEntity>();for(int i=0;i<value.items().size();i++){var source=value.items().get(i);var item=new CargoManifestItemEntity();item.setId(source.id());item.setFreightOrderLineId(source.freightOrderLineId());item.setDescription(source.description());item.setQuantity(source.quantity());item.setPackingInformation(source.packingInformation());item.setCommodityClassification(source.commodityClassification());item.setCustomsApplicable(source.customsApplicable());item.setCustomsInformation(source.customsInformation());item.setHazardous(source.hazardous());item.setHazardousClassification(source.hazardousClassification());item.setHazardousDetails(source.hazardousDetails());item.setFragile(source.fragile());item.setTemperatureSensitive(source.temperatureSensitive());item.setItemOrder(i);items.add(item);}entity.replaceItems(items);return entity;}
 CargoManifest toDomain(CargoManifestEntity e){return new CargoManifest(e.getId(),e.getManifestNumber(),e.getFreightOrderId(),e.getFreightOrderNumber(),e.getItems().stream().map(i->new CargoManifestItem(i.getId(),i.getFreightOrderLineId(),i.getDescription(),i.getQuantity(),i.getPackingInformation(),i.getCommodityClassification(),i.isCustomsApplicable(),i.getCustomsInformation(),i.isHazardous(),i.getHazardousClassification(),i.getHazardousDetails(),i.getFragile(),i.getTemperatureSensitive())).toList(),e.getVersion(),e.getCreatedAt(),e.getUpdatedAt(),e.getCreatedBy(),e.getUpdatedBy(),e.getFinalizedAt(),e.getFinalizedBy());}
}
